local function GetFarstriderConfig()
    local api = _G.FarstriderLib_API
    local data = type(api) == "table" and api.DATA or nil
    return type(data) == "table" and type(data.CONFIG) == "table" and data.CONFIG or nil
end--[[APR_DIAG]]; GetFarstriderConfig = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:24:GetFarstriderConfig#3", GetFarstriderConfig)--[[/APR_DIAG]]

--- Initialize zone detector module
function APR:InitZoneDetectionCache()
    if self.ZoneDetection then return end

    self.ZoneDetection = {
        -- Cache: player zone context (TTL = 1 second)
        playerContextCache = {
            mapIDs = {},
            timestamp = 0,
            ttl = 1
        },
        -- Cache: map hierarchy data (persistent)
        hierarchyCache = {},
        -- Cache: map descendants (persistent)
        descendantsCache = {},
        -- Cache: map info (reduces API calls)
        mapInfoCache = {},
        -- Debug flag (synchronized with settings)
        debug = (self.settings and self.settings.profile and self.settings.profile.zoneDetectionDebug) or false
    }
end--[[APR_DIAG]]; APR.InitZoneDetectionCache = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:31:APR:InitZoneDetectionCache#4", APR.InitZoneDetectionCache)--[[/APR_DIAG]]

---=============================================================================
-- CONTINENT & MAP INFO FUNCTIONS
---=============================================================================

--- Get the continent map ID for a given zone (defaults to the player's current zone).
-- Walks the map parents until reaching the continent level to keep logic unified across expansions.
---@param mapId number|nil Zone MapID (defaults to player's current zone)
---@return number continentID The continent MapID (0 if not found)
function APR:GetContinent(mapId)
    self:Debug("Function: APR:GetContinent()", mapId)
    if not HasMapApi() then
        return 0
    end
    mapId = mapId or C_Map.GetBestMapForUnit("player")

    if mapId then
        local info = C_Map.GetMapInfo(mapId)
        if info then
            -- Walk up parent chain until we find continent (mapType == 2)
            while info and info.mapType and info.mapType > 2 do
                info = C_Map.GetMapInfo(info.parentMapID)
            end
            if info and info.mapType == 2 then
                local config = GetFarstriderConfig()
                local override = config and config.ContinentMapOverrides and
                    config.ContinentMapOverrides[info.mapID] or nil
                return override or info.mapID
            end
        end
    end

    return 0
end--[[APR_DIAG]]; APR.GetContinent = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:60:APR:GetContinent#5", APR.GetContinent)--[[/APR_DIAG]]

--- Return the parent map for the player (zone by default) at a given hierarchy level
--- Uses zone detection system for reliable results
---@param mapType Enum.UIMapType|nil Map type to find (defaults to Zone)
---@return number|nil parentMapID The parent map ID
function APR:GetPlayerParentMapID(mapType)
    mapType = mapType or Enum.UIMapType.Zone

    if not HasMapApi() then
        return nil
    end

    local currentMapId = C_Map.GetBestMapForUnit('player')
    if not currentMapId then
        return nil
    end

    -- If already at the requested type, return current
    local mapInfo = self:GetMapInfoCached(currentMapId)
    if mapInfo and mapInfo.mapType == mapType then
        return currentMapId
    end

    -- Get parent chain and find first map of requested type
    local chain = self:GetMapParentChain(currentMapId)
    for _, mapID in ipairs(chain) do
        mapInfo = self:GetMapInfoCached(mapID)
        if mapInfo and mapInfo.mapType == mapType then
            return mapID
        end
    end

    -- Fallback to current map if no parent of requested type found
    return currentMapId
end--[[APR_DIAG]]; APR.GetPlayerParentMapID = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:90:APR:GetPlayerParentMapID#6", APR.GetPlayerParentMapID)--[[/APR_DIAG]]

--- Get map info with caching to reduce API calls
---@param mapID number Zone MapID
---@return table|nil mapInfo Map information table
function APR:GetMapInfoCached(mapID)
    if not self:IsValidMapID(mapID) then return nil end
    if not HasMapApi() then
        return nil
    end

    local cache = self.ZoneDetection.mapInfoCache
    if self.performanceLogging then self:CountPerformanceEvent(cache[mapID] and "MapInfoCacheHit" or "MapInfoCacheMiss") end
    if not cache[mapID] then
        cache[mapID] = C_Map.GetMapInfo(mapID)
    end

    return cache[mapID]
end--[[APR_DIAG]]; APR.GetMapInfoCached = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:124:APR:GetMapInfoCached#7", APR.GetMapInfoCached)--[[/APR_DIAG]]

--- Invalidate map info cache (call on significant map changes)
function APR:InvalidateMapInfoCache()
    if self.ZoneDetection and self.ZoneDetection.mapInfoCache then
        wipe(self.ZoneDetection.mapInfoCache)
    end
end--[[APR_DIAG]]; APR.InvalidateMapInfoCache = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:140:APR:InvalidateMapInfoCache#8", APR.InvalidateMapInfoCache)--[[/APR_DIAG]]

---=============================================================================
-- CACHE MANAGEMENT
---=============================================================================

--- Reset player context cache (called on zone change)
function APR:InvalidatePlayerZoneCache()
    if self.ZoneDetection then
        self.ZoneDetection.playerContextCache.timestamp = 0
    end
    -- Also invalidate route zone check throttle
    self._lastRouteZoneCheck = nil
    self._lastRouteZoneResult = nil
    -- Invalidate map info cache
    self:InvalidateMapInfoCache()
end--[[APR_DIAG]]; APR.InvalidatePlayerZoneCache = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:151:APR:InvalidatePlayerZoneCache#9", APR.InvalidatePlayerZoneCache)--[[/APR_DIAG]]

--- Check if cache is still valid
local function IsCacheValid(cache)
    if not cache or not cache.timestamp or cache.timestamp == 0 or not cache.ttl then
        return false
    end
    local now = GetTime and GetTime() or 0
    if not now or now == 0 then
        return false
    end
    local elapsed = now - cache.timestamp
    return elapsed >= 0 and elapsed < cache.ttl
end--[[APR_DIAG]]; IsCacheValid = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:163:IsCacheValid#10", IsCacheValid)--[[/APR_DIAG]]

---=============================================================================
-- CORE HIERARCHY FUNCTIONS
---=============================================================================

--- Get the complete parent hierarchy of a map (bottom-up)
--- Returns: list of mapIDs from current to continent root
---@param mapID number Zone MapID to start from
---@return table parentChain List of parent mapIDs (including mapID itself)
function APR:GetMapParentChain(mapID)
    if not self:IsValidMapID(mapID) then return {} end

    local chain = {}
    local current = mapID
    local maxDepth = 50 -- Prevent infinite loops
    local depth = 0

    while current and current ~= 0 and depth < maxDepth do
        table.insert(chain, current)

        local mapInfo = C_Map.GetMapInfo(current)
        if not mapInfo or not mapInfo.parentMapID or mapInfo.parentMapID == current then
            break
        end

        current = mapInfo.parentMapID
        depth = depth + 1
    end

    return chain
end--[[APR_DIAG]]; APR.GetMapParentChain = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:183:APR:GetMapParentChain#11", APR.GetMapParentChain)--[[/APR_DIAG]]

--- Get all descendants of a map recursively
--- Returns: flat list of all child mapIDs at any depth
---@param parentMapID number Parent MapID to search from
---@param maxDepth number Maximum recursion depth (default: 10)
---@return table descendants List of all child mapIDs
function APR:GetAllMapDescendants(parentMapID, maxDepth)
    if not self:IsValidMapID(parentMapID) then return {} end
    if not HasMapChildrenApi() then
        return {}
    end

    local cached = self.ZoneDetection.descendantsCache[parentMapID]
    if cached then
        return cached
    end

    maxDepth = maxDepth or 10
    local descendants = {}
    local processed = {}

    local function recurse(currentMapID, depth)
        if depth >= maxDepth or processed[currentMapID] then
            return
        end
        processed[currentMapID] = true

        local children = C_Map.GetMapChildrenInfo(currentMapID)
        if not children or #children == 0 then
            return
        end

        for _, childInfo in ipairs(children) do
            if childInfo.mapID and childInfo.mapID ~= 0 then
                table.insert(descendants, childInfo.mapID)
                recurse(childInfo.mapID, depth + 1)
            end
        end
    end--[[APR_DIAG]]; recurse = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:226:recurse#13", recurse)--[[/APR_DIAG]]

    recurse(parentMapID, 0)

    -- Cache the result
    self.ZoneDetection.descendantsCache[parentMapID] = descendants

    return descendants
end--[[APR_DIAG]]; APR.GetAllMapDescendants = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:211:APR:GetAllMapDescendants#12", APR.GetAllMapDescendants)--[[/APR_DIAG]]

---=============================================================================
-- PLAYER CONTEXT RESOLUTION
---=============================================================================

--- Get complete zone context for player
--- Returns all relevant mapIDs: current, parent, continent, and full hierarchy
---@return table context { current, parent, continent, hierarchy, allRelevant }
function APR:ResolvePlayerZoneContext()
    -- Check cache validity
    if IsCacheValid(self.ZoneDetection.playerContextCache) then
        if self.performanceLogging then self:CountPerformanceEvent("PlayerZoneCacheHit") end
        return self.ZoneDetection.playerContextCache.mapIDs
    end
    if self.performanceLogging then self:CountPerformanceEvent("PlayerZoneCacheMiss") end

    if not HasMapApi() then
        return {
            current = nil,
            parent = nil,
            continent = 0,
            hierarchy = {},
            allRelevant = {}
        }
    end

    local context = {}

    -- Get current map (best map for player)
    context.current = C_Map.GetBestMapForUnit("player")

    -- Get parent map (zone level)
    context.parent = self:GetPlayerParentMapID()

    -- Get continent
    context.continent = self:GetContinent()

    -- Get full parent chain (hierarchy from current to root)
    context.hierarchy = self:GetMapParentChain(context.current)

    -- Build comprehensive list
    context.allRelevant = {}
    if context.current then table.insert(context.allRelevant, context.current) end
    if context.parent then table.insert(context.allRelevant, context.parent) end
    if context.continent then table.insert(context.allRelevant, context.continent) end
    for _, mapID in ipairs(context.hierarchy or {}) do
        if not self:Contains(context.allRelevant, mapID) then
            table.insert(context.allRelevant, mapID)
        end
    end

    -- Update cache (FIX: actually store the context!)
    self.ZoneDetection.playerContextCache.mapIDs = context
    self.ZoneDetection.playerContextCache.timestamp = GetTime and GetTime() or 0

    return context
end--[[APR_DIAG]]; APR.ResolvePlayerZoneContext = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:260:APR:ResolvePlayerZoneContext#14", APR.ResolvePlayerZoneContext)--[[/APR_DIAG]]

---=============================================================================
-- ZONE MATCHING FUNCTIONS
---=============================================================================

--- Check if any of player maps match step zones (simple)
---@param playerContext table Player zone context
---@param stepZones table Zone mapIDs for step
---@return boolean
function APR:CheckDirectMatch(playerContext, stepZones)
    if not playerContext or not stepZones or #stepZones == 0 then
        return false
    end

    for _, playerMapID in ipairs(playerContext.allRelevant or {}) do
        if self:Contains(stepZones, playerMapID) then
            return true
        end
    end

    return false
end--[[APR_DIAG]]; APR.CheckDirectMatch = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:318:APR:CheckDirectMatch#15", APR.CheckDirectMatch)--[[/APR_DIAG]]

--- Check if player ancestry matches step zones (hierarchy climbing)
---@param playerContext table Player zone context
---@param stepZones table Zone mapIDs for step
---@return boolean
function APR:CheckHierarchyMatch(playerContext, stepZones)
    if not playerContext or not playerContext.hierarchy or not stepZones then
        return false
    end

    for _, mapID in ipairs(playerContext.hierarchy) do
        if self:Contains(stepZones, mapID) then
            return true
        end
    end

    return false
end--[[APR_DIAG]]; APR.CheckHierarchyMatch = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:336:APR:CheckHierarchyMatch#16", APR.CheckHierarchyMatch)--[[/APR_DIAG]]

--- Check if any player map is child of step zones (hierarchy descending)
---@param playerContext table Player zone context
---@param stepZones table Zone mapIDs for step
---@return boolean
function APR:CheckDescendantMatch(playerContext, stepZones)
    if not playerContext or not stepZones or #stepZones == 0 then
        return false
    end

    for _, stepMapID in ipairs(stepZones) do
        local descendants = self:GetAllMapDescendants(stepMapID, 10)
        if self:ContainsAny(descendants, playerContext.allRelevant) then
            return true
        end
    end

    return false
end--[[APR_DIAG]]; APR.CheckDescendantMatch = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:354:APR:CheckDescendantMatch#17", APR.CheckDescendantMatch)--[[/APR_DIAG]]

--- Check if player is on same continent as step zones
---@param playerContext table Player zone context
---@param stepZones table Zone mapIDs for step
---@return boolean
function APR:CheckContinentMatch(playerContext, stepZones)
    if not playerContext or not stepZones or #stepZones == 0 then
        return false
    end

    local playerContinent = playerContext.continent
    if not playerContinent or playerContinent == 0 then
        return false
    end

    for _, stepMapID in ipairs(stepZones) do
        local stepContinent = self:GetContinent(stepMapID)
        if stepContinent == playerContinent then
            return true
        end
    end

    return false
end--[[APR_DIAG]]; APR.CheckContinentMatch = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:373:APR:CheckContinentMatch#18", APR.CheckContinentMatch)--[[/APR_DIAG]]

-- Follow outdoor ancestry symmetrically, including a city's parent zone.
-- Do not cross dungeon maps, unknown hierarchy, or Farstrider isolation groups.
local function GetOutdoorMapContext(self, mapID)
    local config = GetFarstriderConfig() or {}
    local visited, isolation, outerZone = {}, nil, nil
    for _ = 1, 50 do
        if not mapID or mapID == 0 or visited[mapID] then return nil end
        visited[mapID] = true
        local info = self:GetMapInfoCached(mapID)
        if not info then return nil end
        local override = config.MapTypeOverrides and config.MapTypeOverrides[mapID]
        local mapType = override and override.mapType or info.mapType
        if mapType ~= Enum.UIMapType.Zone and mapType ~= (Enum.UIMapType.Micro or 5)
            and mapType ~= (Enum.UIMapType.Continent or 2) then return nil end
        local group = config.IsolatedAreas and config.IsolatedAreas[mapID]
        if group ~= nil and isolation == nil then isolation = group end
        local continentOverride = config.ContinentMapOverrides and config.ContinentMapOverrides[mapID]
        if mapType == (Enum.UIMapType.Continent or 2) or continentOverride then
            return { isolation = isolation, continent = continentOverride or mapID,
                isolatedContinent = config.IsolatedContinents and config.IsolatedContinents[mapID],
                outerZone = outerZone }
        end
        outerZone = mapID
        mapID = info.parentMapID
    end
end--[[APR_DIAG]]; GetOutdoorMapContext = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:395:GetOutdoorMapContext#19", GetOutdoorMapContext)--[[/APR_DIAG]]

--- Accept a nearby step across connected outdoor maps, including nested cities.
-- Shared world coordinates establish proximity; the solver still checks whether
-- a transport action is required before APR publishes ordinary step guidance.
function APR:IsNearbyStepInConnectedZone(step, playerContext, fallbackMapID)
    if not step or (IsInInstance and IsInInstance())
        or (self.GetScenarioMapIDForStep and self:GetScenarioMapIDForStep(step)) then return false end
    local limit = self.Arrow and self.Arrow.MaxDistanceWrongZone
    if not limit or not C_Map.GetWorldPosFromMapPos then return false end
    local coord, coordZone = self:GetStepCoord(step, fallbackMapID)
    if not coord then return false end
    local zone = coordZone or coord.mapID or self:GetPreferredStepZone(step, fallbackMapID)
    local playerMap = playerContext and playerContext.current or C_Map.GetBestMapForUnit("player")
    if not playerMap or not zone then return false end
    local playerY, playerX, _, instanceID = UnitPosition("player")
    local targetInstance = C_Map.GetWorldPosFromMapPos(zone, CreateVector2D(0.5, 0.5))
    if not playerX or not playerY or instanceID == nil or targetInstance ~= instanceID then return false end
    local dx, dy = playerX - coord.x, playerY - coord.y
    if dx * dx + dy * dy >= limit * limit then return false end
    local source = GetOutdoorMapContext(self, playerMap)
    local target = GetOutdoorMapContext(self, zone)
    if not source or not target or source.continent ~= target.continent
        or source.isolation ~= target.isolation then return false end
    if source.isolatedContinent or target.isolatedContinent then
        return source.outerZone == target.outerZone
    end
    return true
end--[[APR_DIAG]]; APR.IsNearbyStepInConnectedZone = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:423:APR:IsNearbyStepInConnectedZone#20", APR.IsNearbyStepInConnectedZone)--[[/APR_DIAG]]

--- Check if player is in special instance content
---@return boolean
function APR:IsInSpecialContent()
    if IsInInstance then
        local inInstance, instanceType = IsInInstance()
        if inInstance then
            return instanceType == "scenario" or instanceType == "party"
                or instanceType == "raid"
        end
    end

    return false
end--[[APR_DIAG]]; APR.IsInSpecialContent = APRTrace("APR-Core/utils/ZoneDetectionUtils.lua:450:APR:IsInSpecialContent#21", APR.IsInSpecialContent)--[[/APR_DIAG]]

